Incluir agrupamentos: agrupamentos no retorno de semente() (dados.js:244, ao lado de clinicas) e criar em store.js, junto de clinica()/nomeClinica() (store.js:48-49), o bloco de seletores canônicos que todas as telas vão usar:

function agrupamento(id){ return porId(estado.agrupamentos, id); }
function nomeAgrupamento(id){ var g = agrupamento(id); return g ? g.nome : '—'; }
function clinicasDoAgrupamento(id){ var g = agrupamento(id); return g ? g.clinicas.map(clinica) : []; }
function agrupamentoDaClinica(clinicaId){ var c = clinica(clinicaId); return c ? agrupamento(c.agrupamentoId) : null; }
function faixaCadeiras(clinicaId){ var c = clinica(clinicaId); return [c.primeiraCadeira, c.primeiraCadeira + c.cadeiras - 1]; }
function faixaAgrupamento(id){ var l = clinicasDoAgrupamento(id); return [l[0].primeiraCadeira, l[1].primeiraCadeira + l[1].cadeiras - 1]; }
function clinicaDaCadeira(n){ for (var i=0;i<estado.clinicas.length;i++){ var f = faixaCadeiras(estado.clinicas[i].id); if (n>=f[0] && n<=f[1]) return estado.clinicas[i]; } return null; }

Exportar todos em global.Store (store.js:511-541).

